def protect(text):
    """The note is read raw, so a backslash outside code means itself: double it for commonmark."""
    out, fence = [], False
    for line in text.split("\n"):
        if line.lstrip().startswith("```"):
            fence = not fence
            out.append(line)
            continue
        if fence:
            out.append(line)
            continue
        parts = line.split("`")
        for i in range(0, len(parts), 2):
            parts[i] = parts[i].replace("\\", "\\\\")
        out.append("`".join(parts))
    return "\n".join(out)


